function sourcePresentationMatches(text, expected) {
  if (typeof text !== 'string' || text.length !== expected[0]) return false;
  let value = 2166136261;
  for (let index = 0; index < text.length; index++) value = Math.imul(value ^ text.charCodeAt(index), 16777619) >>> 0;
  return value === expected[1];
}
export function publicSourcePresentation(source, reading = source, workId = source?.work?.id) {
  const saved = sourceViews[workId]?.[source?.id]?.find(view => view.sha256 === source?.sha256 && sourcePresentationMatches(source?.text,view.body));
  if (!saved || !Array.isArray(source?.paragraphs) || !Array.isArray(reading?.paragraphs)) return {};
  const matches = rows => rows.length === saved.rows.length && rows.every((row, index) => {
    const [id, fingerprint] = saved.rows[index], canonical = source.paragraphs[index];
    return row?.id === id && canonical?.id === id && row?.text === canonical?.text && sourcePresentationMatches(canonical?.text,fingerprint);
  });
  // A different rendition never borrows canonical offsets, paragraph joins or
  // note removal, even when it retains the same registered passage IDs.
  if (!matches(source.paragraphs) || !matches(reading.paragraphs)) return {};
  return {chapter:{beautiful_typeset:true}, passages:Object.fromEntries(saved.rows.map(([id,,hints]) => [id,hints]))};
}
